mapper.select:
/* DailyJoinMapper.selectUserIdDupleCnt */
SELECT COUNT(*)
FROM (

    SELECT 1
      FROM TB_DAILY_USER
     WHERE USER_ID = #{userId}

       AND NOT (CMPNY_CD = #{cmpnyCd} AND USER_CD = #{reuseUserCd})

     LIMIT 1
) T

/* DailyJoinMapper.selectActiveUserIdDupleCnt */
SELECT COUNT(*)
FROM (

    SELECT 1
      FROM TB_DAILY_USER
     WHERE USER_ID  = #{userId}
       AND USE_YN   = 'Y'
     LIMIT 1
) T

/* DailyJoinMapper.selectMblNoDupleCnt */
SELECT COUNT(*)
FROM (
    SELECT 1
      FROM TB_DAILY_USER
     WHERE CMPNY_CD    = #{cmpnyCd}
       AND MBL_NO_HMAC = #{mblNoHmac}
       AND USE_YN      = 'Y'
     LIMIT 1
) T

/* DailyJoinMapper.selectActiveBlacklistCnt */
SELECT COUNT(*)
FROM (
    SELECT 1
      FROM TB_DAILY_BLACKLIST
     WHERE CMPNY_CD    = #{cmpnyCd}
       AND MBL_NO_HMAC = #{mblNoHmac}
       AND USE_YN      = 'Y'
     LIMIT 1
) T

/* DailyJoinMapper.selectSmsVerifiedSmsId */
SELECT SMS_ID
  FROM TB_SMS_AUTH_CODE
 WHERE MBL_NO_HMAC = #{mblNoHmac}
   AND AUTH_CD     = #{certNo}
   AND PURPOSE_CD  = 'SELF_JOIN'
   AND VERIFIED_YN = 'Y'
   AND UPDATE_DATE  >=  DATE_SUB(NOW(), INTERVAL 10 MINUTE)
 ORDER BY UPDATE_DATE DESC
 LIMIT 1

/* DailyJoinMapper.selectMirrorSiteCnt */
SELECT COUNT(1)
FROM TB_SITE A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.SITE_CD  = #{siteCd}
  AND A.LINK_SRC_CMPNY_CD IS NOT NULL

/* DailyJoinMapper.selectLinkPolicyUseYn */
SELECT USE_YN
FROM TB_DAILY_USER_LINK_POLICY
WHERE CMPNY_CD = #{cmpnyCd}
  AND SITE_CD  = #{siteCd}

/* DailyJoinMapper.selectFirstEmptySlotNo */
SELECT SLOT_NO
FROM TB_DAILY_USER_SLOT
WHERE CMPNY_CD    = #{cmpnyCd}
  AND SITE_CD     = #{siteCd}
  AND USE_YN      = 'Y'
  AND SLOT_STATUS = '01'                    
  AND (CURR_USER_CD IS NULL OR CURR_USER_CD = '')
ORDER BY CAST(SLOT_NO AS UNSIGNED)
LIMIT 1

/* DailyJoinMapper.selectSlotNoOccupiedByUser */
SELECT SLOT_NO
FROM TB_DAILY_USER_SLOT
WHERE CMPNY_CD     = #{cmpnyCd}
  AND SITE_CD      = #{siteCd}
  AND CURR_USER_CD = #{userCd}
  AND SLOT_STATUS  = '02'                    
ORDER BY CAST(SLOT_NO AS UNSIGNED)
LIMIT 1
FOR UPDATE

/* DailyJoinMapper.selectActiveDailyUserMblDupleCntExcept */
SELECT COUNT(*)
FROM (
    SELECT 1
      FROM TB_DAILY_USER
     WHERE CMPNY_CD    = #{cmpnyCd}
       AND MBL_NO_HMAC = #{mblNoHmac}
       AND USE_YN      = 'Y'
       AND USER_CD  <>  #{userCd}
     LIMIT 1
) T

/* DailyJoinMapper.selectDailyUserCd */
SELECT CONCAT('D', DATE_FORMAT(NOW(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{cmpnyCd}, 'DAILY_USER'))
FROM DUAL

