    #{cmpnyCd}
    , #{siteCd}
    , #{userCd}
    , #{userId}
    , #{userNm}
    , #{userPw}

    , #{mblNoEnc}
    , #{mblNoHmac}
    , #{mblNoLast4}

    , #{regType}
    , #{useYn}
    , #{accountStatus}
    , DATE_FORMAT(NOW(), '%Y%m%d')

    , #{userCd}
    , NOW()
    , #{userCd}
    , NOW()
)

