/* DailyJoinMapper.updateDailyUserSlotCurrUserCd */
UPDATE TB_DAILY_USER_SLOT
SET CURR_USER_CD = #{userCd}
    , SLOT_TYPE   = #{slotType}
    , SLOT_STATUS = #{slotStatus}
    , UPDATE_NO   = #{userCd}
    , UPDATE_DATE = NOW()
WHERE CMPNY_CD    = #{cmpnyCd}
  AND SITE_CD     = #{siteCd}
  AND SLOT_NO     = #{slotNo}
  AND USE_YN      = 'Y'
  AND SLOT_STATUS = '01'                    
  AND (CURR_USER_CD IS NULL OR CURR_USER_CD = '')

mapper.insert:
/* DailyJoinMapper.insertTermsUserAgrMgmt */
INSERT INTO TB_TERMS_USER_AGR_MGMT (
    CMPNY_CD
    , USER_CD
    , TERMS_ID
    , TERMS_VERSION
    , AGR_YN
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
    #{cmpnyCd}
    , #{userCd}
    , #{termsId}
    , #{termsVersion}
    , #{agrYn}
    , #{userCd}
    , NOW()
) AS NEW
/* PK=(CMPNY_CD,USER_CD,TERMS_ID,TERMS_VERSION). 옵션2 재활성은 USER_CD 를 재사용하므로,
   동일 약관 버전 재동의 시 PK 충돌로 트랜잭션이 롤백되는 것을 방지한다.
   버전이 바뀌면 새 행(이력 보존), 같은 버전 재동의면 동의값/시각만 갱신(멱등). */
ON DUPLICATE KEY UPDATE
    AGR_YN      = NEW.AGR_YN
    , INSERT_NO   = NEW.INSERT_NO
    , INSERT_DATE = NOW()

