/* DailyJoinMapper.reactivateDailyUser */
UPDATE TB_DAILY_USER
SET USE_YN                 = 'Y'
    , ACCOUNT_STATUS        = #{accountStatus}
    , SITE_CD               = #{siteCd}
    , USER_ID               = #{userId}
    , USER_NM               = #{userNm}
    , USER_PW               = #{userPw}
    , MBL_NO_ENC            = #{mblNoEnc}
    , MBL_NO_HMAC           = #{mblNoHmac}
    , MBL_NO_LAST4          = #{mblNoLast4}
    , WORK_EXPIRE_DATE      = DATE_FORMAT(NOW(), '%Y%m%d')
    , WITHDRAWAL_DATE       = NULL
    , PWD_FAIL_CNT          = 0
    , PWD_LOCK_YN           = 'N'
    , PWD_LOCK_EXPIRE_DTIME = NULL
    , UPDATE_NO             = #{userCd}
    , UPDATE_DATE           = NOW()
WHERE CMPNY_CD = #{cmpnyCd}
  AND USER_CD  = #{userCd}

/* DailyJoinMapper.reactivateTbUser */
UPDATE TB_USER
SET USE_YN          = 'Y'
    , ACCOUNT_STATUS = #{accountStatus}
    , SITE_CD        = #{siteCd}
    , USER_ID        = #{userId}
    , USER_NM        = #{userNm}
    , USER_PW        = #{userPw}
    , MBL_NO_ENC     = #{mblNoEnc}
    , MBL_NO_HMAC    = #{mblNoHmac}
    , MBL_NO_LAST4   = #{mblNoLast4}
    , UPDATE_NO      = #{userCd}
    , UPDATE_DATE    = NOW()
WHERE CMPNY_CD        = #{cmpnyCd}
  AND USER_CD         = #{userCd}
  AND EMPLOYMENT_TYPE = 'DAILY'

